-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2023/1, revalida-2023-1): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 31 correções de texto em 22 questões (22 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2023-1';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2023_1_q004","code":"REV-2023.1-Q004","campos":{"statement":{"antes_md5":"9e8d0e4661b07dc41628ff56303a9688","depois":"Uma paciente com 21 anos, nuligesta, comparece à consulta em um centro de saúde com queixa de amenorreia há 6 meses, acne com pústulas, aumento de pelos, principalmente na face e nos membros inferiores. Relata dificuldade em perder peso e ciclos menstruais irregulares e longos desde a menarca. Afirma ser sexualmente ativa. É realizado, durante o atendimento, teste rápido para gravidez, com resultado negativo. Ao exame físico, apresenta índice de massa corpórea de 30 kg/m², pressão arterial de 120 × 70 mmHg. Considerando-se o quadro clínico da paciente, qual é a conduta inicial mais adequada no momento desse atendimento?"}}},{"id":"revalida_2023_1_q019","code":"REV-2023.1-Q019","campos":{"statement":{"antes_md5":"6ea0f55a155cbbbabeabe7eb9144b654","depois":"Uma paciente com 45 anos, casada, G2P2, 2 partos normais, comparece ao ambulatório de ginecologia para avaliação de resultado de ultrassonografia transvaginal que evidenciou útero em anteversoflexão, contornos regulares, miométrio heterogêneo, com pequenos miomas intramurais e subserosos, estando o maior localizado na parede posterior/fúndica, intramural, medindo 2,0 × 1,9 cm; volume uterino de 198,6 cm³ (valor do percentil 95 para a faixa etária e paridade - 136 cm³); ovários de topografia, dimensões e ecotextura usuais; endométrio centrado, regular, medindo 6,8 mm de espessura (normal para faixa etária e paridade). A paciente relata ciclos menstruais regulares de 28 dias, fluxo moderado com duração de 5 dias, nega dismenorreia ou dispareunia. Afirma que é sexualmente ativa e que o marido é vasectomizado. Para essa paciente, a conduta mais adequada é"}}},{"id":"revalida_2023_1_q023","code":"REV-2023.1-Q023","campos":{"statement":{"antes_md5":"af34bf8f4ee82e891ba3b93d0126ebcb","depois":"Uma adolescente com 16 anos procura a unidade básica de saúde para avaliação de uma mancha na pele. Relata que, há cerca de 1 mês, desenvolveu uma lesão caracterizada como uma placa eritematosa, liquenificada e pruriginosa, localizada acima da região umbilical, próxima ao local onde colocou um piercing. Ao ser examinada, a lesão foi confirmada e constatou-se também que o desenvolvimento puberal era M1P1, conforme os critérios de Tanner. A adolescente também apresentava baixa estatura, pescoço alado e implantação baixa de orelhas. Ao ser questionada sobre o fluxo menstrual, ela informou que ainda não tinha menstruado. Considerando-se o quadro clínico e o exame físico descritos, os diagnósticos mais prováveis são"}}},{"id":"revalida_2023_1_q026","code":"REV-2023.1-Q026","campos":{"statement":{"antes_md5":"fd85545368b8459793df602a096d6fe3","depois":"Uma paciente com 22 anos foi atendida na atenção primária, acompanhada pelos pais, que estão preocupados com sua perda de peso. Eles contam que, desde os 14 anos, ela come muito pouco e que já esteve internada para “ser alimentada”. A paciente também refere ansiedade e palpitações que estão afetando o seu dia a dia. Os pais dizem que não sabem exatamente o quanto a paciente está comendo agora, mas que ela não provoca vômitos ou abusa de medicamentos. Ao exame físico, o índice de massa corporal da paciente é 14,8 kg/m² e sua pressão arterial está normal (100 × 60 mmHg), mas ela apresenta hipotensão postural assintomática (queda de 18 mmHg na diastólica), desidratação e frequência cardíaca de 42 batimentos por minuto. Diante dessa situação, o médico deve"}}},{"id":"revalida_2023_1_q031","code":"REV-2023.1-Q031","campos":{"B":{"antes_md5":"f6641ff34147a816977edbf952571059","depois":"O diagnóstico provável do caso é sustentado apenas se estiverem presentes mais de 250 polimorfonucleares/mm³ no líquido analisado."}}},{"id":"revalida_2023_1_q032","code":"REV-2023.1-Q032","campos":{"statement":{"antes_md5":"42f86acdef8037f280480c73ff79532c","depois":"Uma paciente com 54 anos apresenta tosse com expectoração e astenia há 5 dias, acompanhada de dispneia aos médios esforços e um pico febril. Ao exame físico, encontra-se consciente, contatuante, descorada (+2/+4), desidratada (+2/+4), com pressão arterial de 90 × 60 mmHg, frequência respiratória de 23 incursões respiratórias por minuto, frequência cardíaca de 120 batimentos por minuto, saturação O₂ de 90% em ar ambiente, murmúrio vesicular presente em hemitórax direito e diminuído em hemitórax esquerdo, abolido em base esquerda, sem ruídos adventícios; radiografia de tórax demonstrou derrame pleural à esquerda. Foi realizada toracocentese, seguida de drenagem pleural fechada à esquerda. O líquido, de aspecto turvo, foi encaminhado para análise, sendo confirmado empiema pleural. Acerca do líquido analisado, infere-se que"}}},{"id":"revalida_2023_1_q043","code":"REV-2023.1-Q043","campos":{"statement":{"antes_md5":"115c6937d328a1af3e72b1a35556d364","depois":"Um paciente desnutrido, com 6 meses, deu entrada no pronto-socorro, acompanhado por familiares que relatam diarreia abundante e piora progressiva do nível de consciência, que vem ocorrendo há 2 dias. Ao exame, o paciente encontra--se desidratado, hipocorado, sonolento, comatoso e sem sinais localizatórios. Mantido em ar ambiente, colheu-se uma gasometria arterial, que revelou pH = 7,22; pressão parcial de CO₂ de 48 mmHg; pressão parcial de O₂ de 75 mmHg; saturação de O₂ de 94%; bicarbonato de 12,5 mEq/L e excesso de bases (BE) = -13. Considerando o quadro descrito, assinale a opção que apresenta o diagnóstico correto para o caso."}}},{"id":"revalida_2023_1_q046","code":"REV-2023.1-Q046","campos":{"statement":{"antes_md5":"1a1973857f1145a089f22f948bf9c7c9","depois":"Um homem com 78 anos, acamado há meses em função de quadro demencial avançado, chega à unidade de emergência com quadro de rebaixamento do nível de consciência, febre e hipotensão arterial. Segundo familiares, o paciente vem apresentando tosse desde a ocorrência, há 3 dias, de episódio compatível com broncoaspiração durante tentativa de alimentação por via oral. Relatam que, nos últimos 2 dias, ele passou a se mostrar mais apático, não interagindo minimamente com os familiares, nem aceitando alimentação e que, no dia de hoje, surgiu febre e a acompanhante aferiu pressão arterial de 90 × 60 mmHg, uma queda de cerca de 40 mmHg na pressão sistólica em relação ao parâmetro habitual do paciente. Ao exame físico, é confirmada hipotensão arterial sistêmica (88 × 48 mmHg), além de sonolência (escore de coma de Glasgow de 9 pontos), desidratação (+2/+4), descoramento de mucosas (+1/+4), taquicardia (120 batimentos por minuto), taquipneia (26 incursões respiratórias por minuto) e presença de roncos difusos, com estertores crepitantes na base direita. Exames laboratoriais iniciais revelam anemia (hemoglobina de 8,5 g/dL - valor de referência [VR]: 13-17 g/dL), elevação de creatinina (2,3 mg/dL - VR: 0,8-1,2 mg/dL), ureia (102 mg/dL - VR: 20-40 mg/dL) e lactato (5,1 mmol/L - VR: <= 2,0 mmol/L), além de acidose metabólica e hipoxemia. São colhidas hemoculturas. O paciente é monitorizado adequadamente, submetido a oferta suplementar de oxigênio, e inicia-se o tratamento indicado para o quadro clínico que apresenta. Além da antibioticoterapia de amplo espectro adequada, a conduta prioritária a ser adotada para esse paciente ainda nas primeiras horas de abordagem é"}}},{"id":"revalida_2023_1_q047","code":"REV-2023.1-Q047","campos":{"statement":{"antes_md5":"60b6bbdaeee64e96265603c6ac37a4f0","depois":"Uma paciente com 40 anos, índice de massa corpórea de 38kg/m², com história de colelitíase sintomática há 2 anos, apresenta-se para cirurgia de colecistectomia videolaparoscópica. Os resultados de seus exames laboratoriais são normais e a ultrassonografia de abdome mostra múltiplos cálculos em vesícula biliar. É realizada a operação, descrita como tecnicamente difícil em razão da obesidade e das aderências inflamatórias no leito vesicular. A paciente foi encaminhada à enfermaria, acordada e sem queixas. Foram reiniciadas dieta e deambulação nas primeiras 24 horas de pós-operatório. Após 36 horas de pós-operatório, apresentou pico febril de 39 °C, dor abdominal e discreta icterícia. Novos exames laboratoriais mostraram leucograma de 20.500 leucócitos com 8% bastões, bilirrubina direta 2,0 mg/dL, bilirrubina indireta 1,0 mg/dL, aspartatoaminotransferase 60 U/L, alanina aminotransferase 80 U/L, fosfatase alcalina 230 U/L e gamaglutamiltransferase 450 U/L. A paciente evoluiu, em 4 horas, com hipotensão, prostração e queda do estado geral. Acerca desse quadro clínico, assinale a opção correta."}}},{"id":"revalida_2023_1_q053","code":"REV-2023.1-Q053","campos":{"statement":{"antes_md5":"4ee0008897bee77c2ef7e545d9b8f6b5","depois":"Um pediatra é chamado para atendimento de um recém-nascido (RN) em sala de parto, sendo informado de que a gestante não realizou pré-natal. A criança nasce em apneia. O cordão umbilical foi clampeado imediatamente e o RN é levado à mesa de reanimação. O pediatra realiza os passos iniciais em, no máximo, 30 segundos, mas o RN continua em apneia. Considerando-se o quadro clínico descrito, qual é a conduta adequada nesse momento?"}}},{"id":"revalida_2023_1_q058","code":"REV-2023.1-Q058","campos":{"statement":{"antes_md5":"d61033cc11448c8c97faed43f2529ca3","depois":"Um adolescente de 12 anos, pesando 85 kg e com índice de massa corpórea de 30 kg/m², é atendido na emergência queixando-se de fortes dores no quadril direito e de impotência funcional do membro inferior direito. O pai informa ao médico de plantão que o menino é hipertenso, que realiza um tratamento para emagrecer e nega associação do problema na perna a trauma. Nesse caso, a hipótese diagnóstica mais provável é de"}}},{"id":"revalida_2023_1_q061","code":"REV-2023.1-Q061","campos":{"statement":{"antes_md5":"949fb71b9ad0d52797f3f1c6166fde7a","depois":"Um homem com 50 anos chega ao pronto-socorro após queda da própria altura e dor em pulso direito. Relata perda ponderal de 25 kg nos últimos dois anos, referindo hiporexia e má alimentação. Relata ingestão de bebidas destiladas diariamente há 10 anos, cerca de 500 a 800 ml/dia, nega tabagismo, doenças preexistentes, uso de medicamentos e de drogas ilícitas. O paciente apresenta-se em estado geral ruim, apático, alerta, orientado em espaço, pouco orientado em tempo; sua marcha é atáxica. Ao exame físico, registram-se índice de massa corporal de 18 kg/m²; frequência cardíaca de 100 batimentos por minuto; frequência respiratória de 16 incursões respiratórias por minuto; pressão arterial de 100 × 60 mmHg. Observam-se diplopia, nistagmo e estrabismo convergente bilateral, punho direito edemaciado, além de amnésia retrógrada e distorção ao relatar histórias passadas. Os resultados de seus exames de sangue apresentam: hemoglobina: 13,1 g/dL (valor de referência [VR]: 13-16); hematócrito: 38% (VR: 38-50); leucócitos: 8.890 /mL (VR: 4.000-10.000); plaquetas: 280.000/mL (VR: 150.000-400.00); sódio: 140 mEq/L (VR: 135-145); potássio: 3,8 mg/dL (VR: 3,5-5,5); cálcio: 8,4 mg/dL (VR: 8,5–10,4); magnésio: 0,9 mg/dL (VR: 1,8-2,7); glicose: 68 mg/dL (VR: 70-99); TGO/AST: 70 U/L (VR: <40); TGP/ALT: 85 U/L (VR: < 40); vitamina B1: 15 mmol/L (VR: 60-120). No resultado da ressonância magnética plano axial T2, observam-se sinais hiperintensos na região do tecto e na substância cinzenta próxima ao aqueduto cerebral. Considerando-se esse quadro clínico e a suspeita diagnóstica da Síndrome de Wernick Korsakoff, quais seriam, respectivamente, o fator etiopatogênico dessa síndrome e a conduta terapêutica adequada para o paciente?"}}},{"id":"revalida_2023_1_q071","code":"REV-2023.1-Q071","campos":{"statement":{"antes_md5":"75443652c6317d325ff1d2e4fc301bfa","depois":"Um homem com 38 anos foi encaminhado ao ambulatório de referência em infectologia do seu município devido a episódios de cefaleia, confusão mental e febre (até 38,5 °C) ocorridos há cerca de uma semana, tendo havido perda de peso no último mês (peso habitual = 70 kg). Ele relata que, no dia anterior, iniciou com rebaixamento do nível de consciência, encontrando-se letárgico no momento da consulta. Nega tosse ou diarreia. Os familiares contam que o paciente é tabagista e que faz consumo excessivo de bebida alcoólica. Os exames iniciais mostraram leucócitos: 3.200/mm³, com 69% de neutrófilos, 21% de linfócitos e 10% de eosinófilos; anemia hipocrômica, microcítica, com anisocitose; plaquetas normais; velocidade de hemossedimentação: 120 mm na 1ª hora; ureia, creatinina, TGO/AST, TGP/ALT, eletrólitos normais. Foi realizada a análise do líquido cefalorraquidiano (LCR), que mostrou 200 leucócitos/mm³, com 78% de linfócitos, níveis elevados de proteína, baixos níveis de glicose e tinta nanquim negativa. Considerando-se o quadro descrito, a hipótese diagnóstica pertinente ao caso é de"}}},{"id":"revalida_2023_1_q080","code":"REV-2023.1-Q080","campos":{"statement":{"antes_md5":"f2f3a69e427624c8cb235220942b0d46","depois":"Uma criança com 8 anos chega, com sua mãe, à unidade de saúde da família com queixa de dispneia e sibilância há cerca de 2 horas. A criança tem histórico de asma, em acompanhamento na unidade, fazendo uso de beclometasona 200 mcg por dia. Quando questionada sobre o controle das crises da criança, a mãe refere que vinha usando salbutamol 100 mcg, 3 a 4 vezes por semana, devido a quadros de tosse seca e discreto desconforto respiratório. Relata que, hoje, porém, mesmo após 2 puffs de salbutamol, os sintomas apresentados pela criança estavam mais intensos e persistentes. A criança demonstra desconforto e agitação, com fala entrecortada, frequência respiratória de 32 incursões respiratórias por minuto, frequência cardíaca de 110 batimentos por minuto, saturação de O₂ de 89% em ar ambiente, sibilos difusos e tiragem intercostal. Nesse caso, as condutas médicas para o controle da crise e para o tratamento de manutenção contra a asma devem ser, respectivamente,"}}},{"id":"revalida_2023_1_q081","code":"REV-2023.1-Q081","campos":{"statement":{"antes_md5":"54ee366df17dafd5f967658cdd00fcce","depois":"Uma paciente com 57 anos, assintomática, foi submetida a exames complementares iniciais de check-up que revelaram a presença de hipercalcemia leve a moderada (11,5 mg/dL – valor de referência [VR]: 8,0-10,5 mg/dL), sendo referenciada para ambulatório de endocrinologia de um hospital terciário. Ao ser atendida nesse serviço, foi solicitada a dosagem de PTH (paratormônio), cujo resultado revelou-se aumentado (189 pg/mL - VR: 10-65 pg/mL). Considerada a hipótese diagnóstica principal, foram realizados outros exames complementares que revelaram os seguintes achados: ultrassonografia abdominal com cálculos em cálices renais e aspecto de nefrocalcinose bilateral, além da presença de colelitíase em vesícula biliar; densitometria óssea com escore-T menor que - 2,5 em coluna lombar e colo femural; calciúria de 600 mg em 24 horas. Com vistas a possível ressecção cirúrgica minimamente invasiva de lesão adenomatosa, é feito um exame de SPECT com ⁹⁹ᵐTc-sestamibi, que revela hipercaptação nodular de cerca de 2,5 cm na base do pescoço, à direita. Considerando-se esse contexto, que dado é indicativo de intervenção cirúrgica, mesmo estando a paciente assintomática?"}}},{"id":"revalida_2023_1_q085","code":"REV-2023.1-Q085","campos":{"statement":{"antes_md5":"7fa0accbd9b8bf902d1578ba6fd8c59c","depois":"A febre amarela apresentou, no Brasil, dois picos epidêmicos em 2016/2017 e em 2017/2018, afetando estados das regiões Sudeste, Centro-Oeste e Nordeste. Antes disso, ainda em 2014, a doença, que era restrita à região amazônica, vinha reemergindo na região extra-amazônica, com casos na região Sudeste, Sul e Centro-Oeste. O aumento dos casos da doença está relacionado com a expansão da fronteira agrícola, que provoca o desmatamento, a redução das áreas de floresta e o aumento da urbanização, o que contribui ainda mais para a degradação desses ambientes e produz risco de desastres ambientais. Diante desse cenário, um médico de família e comunidade de um município próximo a áreas de desmatamento, visando a prevenção contra possível enfrentamento da febre amarela em seu território, deve"}}},{"id":"revalida_2023_1_q087","code":"REV-2023.1-Q087","campos":{"statement":{"antes_md5":"795bb159061b3a993c1314880cf8a7ab","depois":"Uma paciente com 26 anos, vítima de atropelamento em via pública, chega ao pronto-socorro com colar cervical, imobilizada em prancha longa. Foi entubada, no local do acidente, pelo médico socorrista, devido à alteração do nível de consciência (escala de coma de Glasgow: 6). Na sala de emergência, encontra-se com: pulso de 128 batimentos por minuto, pressão arterial de 90 × 60 mmHg, saturação de O₂ de 89%, ventilada manualmente. A ausculta pulmonar está normal à direita, mas o murmúrio vesicular está muito diminuído em todo o hemitórax esquerdo. A paciente não apresenta desvio de traqueia nem estase jugular. Diante desse quadro, a primeira medida a ser tomada é"}}},{"id":"revalida_2023_1_q094","code":"REV-2023.1-Q094","campos":{"statement":{"antes_md5":"2551db0597f6261e3df9a3a1172ec90b","depois":"Uma mulher de 19 anos comparece a uma unidade de emergência com dor em fossa ilíaca esquerda há 3 dias, mais intensa neste dia. Nega febre e afirma ter relação sexual heterossexual, utilizando-se de condon como meio de anticoncepção, de forma irregular. Refere que a última menstruação ocorreu há 45 dias. Ao exame físico, apresenta pressão arterial de 90 × 50 mmHg, frequência cardíaca de 110 batimentos por minuto, temperatura axilar de 36,7 ºC, abdome doloroso em andar inferior, principalmente em fossa ilíaca esquerda, com descompressão dolorosa. Ao exame especular, nota-se sangramento discreto pelo orifício externo do colo; toque com dor a palpação de região anexial esquerda, útero intrapélvico, colo fechado. Considerando-se o quadro descrito e os dados apresentados, o principal diagnóstico e a conduta adequada são, respectivamente,"}}},{"id":"revalida_2023_1_q096","code":"REV-2023.1-Q096","campos":{"statement":{"antes_md5":"742973c7cbc4259e86e6f992bc6dbaec","depois":"Um homem com 22 anos, pesando 75 kg, sofreu múltiplas fraturas e contusão pulmonar em acidente automobilístico, evoluindo com SARA (Síndrome da Angústia Respiratória do Adulto), estando em ventilação mecânica há 7 dias. Apresenta escala de coma de Glasgow < 8. À ausculta pulmonar, observa-se murmúrio vesicular presente, diminuído em bases, associado a estertores finos em bases. A radiografia de tórax mostra imagens sugestivas de consolidações difusas em pulmão direito e esquerdo, típicas de SARA, com infiltrado intersticial difuso. A tomografia de crânio demonstra imagem compatível com hematoma subdural à direita. O paciente apresenta, ainda, pH: 7,35 (valor de referência [VR]: 7,35-7,45); pressão parcial de CO²: 45 mmHg (VR: 35-45 mmHg); pressão parcial de O²: 85 mmHg (VR: 80 a 100 mmHg); bicarbonato: 24 mmol (VR: 22 a 26 mmol). Nesse caso, de acordo com a Associação de Medicina Intensiva Brasileira (AMIB) – Diretrizes Brasileiras de Ventilação Mecânica, recomenda-se"}}},{"id":"revalida_2023_1_q097","code":"REV-2023.1-Q097","campos":{"statement":{"antes_md5":"5dba8d30c423599e8ae34dff4edd22b6","depois":"Um paciente com 65 anos procura a unidade de pronto atendimento com queixa de ter acordado com dor abdominal, súbita, difusa, de intensidade crescente. Conta que fez uso de medicação sintomática e apresentou 2 episódios de vômitos. Nega sintomas urinários e alteração do hábito intestinal. Relata tabagismo (consumo de 60 maços/ano) e etilismo habitual (2 doses de destilado/dia), além das seguintes comorbidades: hipertensão arterial, em uso de atenolol, losartana, aspirina e sinvastatina; infarto agudo do miocárdio há 10 anos. Acrescenta que passou por uma cirurgia prévia, de urgência, de úlcera no estômago há 18 anos. Ao exame físico, apresenta-se: obeso, em regular estado geral, agitado. Registram-se, ainda: pressão arterial de 100 × 60 mmHg; frequência cardíaca de 110 batimentos por minuto; frequência respiratória de 20 incursões respiratórias por minuto; temperatura axilar de 37,8 °C; estando o paciente ictérico (+1/+4), corado, desidratado (+1/+4), com abdome normotenso, doloroso à palpação profunda difusamente, sem sinais de irritação peritoneal. Resultados de seus exames laboratoriais apresentam: hemoglobina: 13 g/dL, leucócitos: 14.000/mm³, amilase: 238 U/L, lipase: 130 U/L, Proteína C Reativa: 8 mg/L, gasometria venosa mostrando Ph: 7,32 e lactato: 27 mg/dL. Nesse caso, a principal hipótese diagnóstica é de abdome agudo"}}},{"id":"revalida_2023_1_q099","code":"REV-2023.1-Q099","campos":{"D":{"antes_md5":"e6a0651e20cdae972713a77ced0e505e","depois":"procurem o atendimento secundário para realização de cirurgia de conização."}}},{"id":"revalida_2023_1_q100","code":"REV-2023.1-Q100","campos":{"statement":{"antes_md5":"6236e53a2adc43b4d38038a1609f9364","depois":"Uma médica iniciou suas atividades em uma equipe de Saúde da Família (ESF) de um grande centro urbano. Na primeira reunião de equipe, questionou de que forma os trabalhadores organizavam seu processo de trabalho para compreender as especificidades e necessidades da população da área adstrita, do ponto de vista dos determinantes sociais da saúde (DSS). Os profissionais participantes da reunião não conseguiram responder a essa pergunta. A seguir é apresentado o modelo de determinantes sociais da saúde (DSS), proposto por Dahlgren e Whitehead. BUSS e PELLEGRINI FILHO, Saneamento e saúde ambiental. Disponível em: <https://publica.ciar.ufg.br/ebooks/saneamento-e-saude-ambiental/modulos/4_modulo_saude/01.html.> Acesso em 03 fev. 23 (adaptado). Considerando o modelo de determinação social da saúde apresentado, os profissionais dessa ESF deveriam"}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2023-1', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2023-1', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2023-1', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2023/1: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 22)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2023-1'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2023-1' and situacao like 'pulado%'
) x order by ordem, resultado;
